INSERT INTO theory_content (chapter_slug, subject_id, concepts_json) VALUES ('telangana-history-en-chapter6-rashtrakutas', 'telangana-history-en', '') ON CONFLICT(chapter_slug) DO UPDATE SET concepts_json = '';
UPDATE theory_content SET concepts_json = concepts_json || '[{"partNumber": 1, "conceptId": "telangana-history-en-chapter6-rashtrakutas-p1", "partName": "Rashtrakutas — Overview and Origin", "bodyMd": "Rashtrakutas occupied the most prominent place in the history of South India. Remaining as feudatories of the Chalukyas of Badami, they established an independent and vast empire after the decline of the Badami Chalukyas. Many districts of Telangana used to be under Rashtrakuta rule, and **Manyakheta** in the Karnataka region remained their capital.\n\n### Theories on Origin\n\nThere are different opinions among historians regarding the origin of the Rashtrakutas — while some scholars held that their political life started in Maharashtra, others argue that their original homeland was Karnataka.\n\n1.  **Dr. Fleet** felt that Rashtrakutas belonged to the Rathor descendants of Northern India.\n2.  **R.G. Bhandarkar** opined that the Rajjakas (provincial governors) of the Mauryan days only might have become Rashtrakutas.\n3.  **Dr. Barnal** held that Rashtrakutas were Telugu people who, after some time, came to be called Reddis.\n4.  **Mallampalli Somasekhara Sarma** similarly held the opinion that, remaining as Rattadi or charioteers, the Rashtrakutas were those who later became Reddis of Telugu land.\n5.  **A.S. Altekar** stated that the term \"Rashtrakuta\" remained the name of an employer post, and later, as they established an independent kingdom, that name became established as their dynastic name.\n\n**The employer-name theory:** The word Rashtrakuta was not the name of a race — just as \"gramakuta\" means a village official in ancient days, \"Rashtrakuta\" too indicates an employer name. During the Mauryan period, a person known as \"Rashtriya\" used to be the viceroy of bigger regions such as Gujarat and Kathiawar. In the first centuries A.D., Rathikas and Maharathikas governed small regions in Maharashtra and Berar, and when the central government became weak, they established independent kingdoms.\n\nIt is learnt that the word \"Rashtrakuta\" was adopted as their dynastic name. Among the Rashtrakutas who became independent, the important ones were those who became the chiefs of **Lattaluru** — the present-day Kannada-speaking Latur in Bidar district. Hence, their mother tongue must have been Kannada only.\n\nDuring the time of the Badami Chalukyas, the Rashtrakutas remained their feudatories. They might have belonged to the Rathika family in Maharashtra areas, or to the Reddi family in Andhra and Karnataka regions. In their dynastic anecdotes, the Rashtrakutas claimed to have originated from **Satyaki**, the brother of Sri Krishna. Ruling Bidar and Maharashtra areas, these Rashtrakutas cooperated in maintaining the prestige of the Badami Chalukya kingdom; when that kingdom disintegrated, they established their own independent kingdom and, within a short time, became the emperors of Dakshinapatha in South India.\n\n* * *", "free": true}, {"partNumber": 2, "conceptId": "telangana-history-en-chapter6-rashtrakutas-p2", "partName": "Rashtrakutas: Political Developments", "bodyMd": "Rashtrakutas ruled for nearly 200 years. The brother of Nannaraju, who ruled the Ellichpur area in 631 A.D., is considered the ancestor in their dynasty.\n\n**Indra Raja I (696 – 710 A.D.)** was the founder of the Rashtrakuta dynasty. He and his successors ruled Manyakheta and Western Telangana areas as feudatories of the Badami Chalukyas. After him, **Govindaraja or Varma I (710 – 725 A.D.)**, **Kanakaraja I (725 – 735 A.D.)** and **Indraraja III (735 – 748 A.D.)** continued as feudatories of the Badami Chalukyas.\n\n### Dantidurga (748 – 758 A.D.)\n\nThe independent Rashtrakuta kingdom was established by Dantidurga, son of Indraraja II. He was highly courageous and of keen temperament.\n\n**Establishing independence**\n\n*   Dantidurga defeated **Keertivarma II** (753 A.D.), the Badami Chalukyan king, and established the independent Rashtrakuta kingdom. The greater part of Telangana came under their empire.\n\n**As a feudatory — early campaigns**\n\n*   Earlier, as feudatory of the Western Chalukyan ruler **Vikramaditya II**, Dantidurga participated in several expeditions and conquered the Pallava, Malwa and Gujarat areas.\n*   In a battle fought in 738 A.D., he severely defeated the Arabs.\n*   Pleased with this great victory, Vikramaditya II gave Dantidurga the titles \"Prithvivallabha\" and \"Khadgavaloka.\"\n\n**Consolidation as independent ruler**\n\n*   Dantidurga occupied the Nasik, Poona, Satara and Kolhapur districts. Becoming overlord of the entire Maharashtra, he assumed the titles \"Maharajadhiraja,\" \"Paramamaheswara\" and \"Paramabhattaraka.\"\n*   By 757 A.D., he had conquered Kanchi, Kalinga, Kosala, Srisailam, Malwa, Lata and Sindhu areas.\n*   The Vayamgadh inscriptions and the inscriptions at the Dasavatara temple in Ellora (also built by Dantidurga) describe his great war victories.\n*   He invaded Malwa, conquered it, and in its capital **Ujjaini** made a \"Hiranyagarbha\" donation to declare his victory.\n*   He gave his daughter in marriage to Pallava king **Nandivarma II**.\n\nIn his short period of rule, Dantidurga established an extensive Rashtrakuta empire and died in 758 A.D.\n\n### Krishna I (758 – 772 A.D.)\n\nAfter Dantidurga, Krishna I ruled the Rashtrakuta kingdom, carrying forward the conquests started by Dantidurga.\n\n*   He occupied Southern Konkan and sent crown-prince **Govinda II** to Vengi; Govinda II defeated Vengi Chalukyan ruler **Vishnuvardhana IV** and occupied some territory.\n*   During Krishna I''s time, rivalry started between the Vengi Chalukyas and the Rashtrakutas — a conflict that would continue for generations.\n*   Krishna I bore the titles \"Subhattunga\" and \"Akalavarshudu.\"\n*   He was also a great patron of art, building the **Kailasanadha temple (rock-cut) at Ellora** — its construction went on for nearly a hundred years, and it has since received recognition as a world heritage site.\n\n### Govinda II (772 – 780 A.D.)\n\nAfter Krishna I, Govinda II ruled between 772–780 A.D. He won victory in the **battle of Gangavadi**, and was called \"Suvarna Govindaraja\" and \"Prabhuta Varsha.\"\n\n### Dhruva Raja or Dhruva (780 – 792 A.D.)\n\nDhruva killed his brother Govinda II, ascended the throne, and then defeated the kings of Kanchi, Gangavadi, Vengi and Malwa.\n\n**Conquests and the Tripartite Struggle**\n\n*   Dhruva defeated the Eastern Chalukyan ruler **Vishnuvardhana IV** and married his daughter **Seelamahadevi**.\n*   He had great courage and capacity — not confining himself to Dakshinapatha or South India, he conquered North India too, making its rulers his feudatories.\n*   Dhruva was the **first Rashtrakuta ruler to enter the Tripartite wars** — the struggle for control of Kanauj fought between the Pala, Pratihara and Rashtrakuta dynasties.\n*   He defeated Pratihara-Kanauj ruler **Vatsaraja**, and as a mark of this victory adopted the \"Ganga-Yamuna torana\" as his kingdom''s emblem.\n\n**Significance of his reign**\n\n*   The Rashtrakuta kingdom, until then a local power, was extended to North India — creating a special place for the Rashtrakutas in the history of India.\n*   Dhruva held the titles \"Srivallabha,\" \"Nirupamavallabha\" and \"Dhanarnava.\" As a result of the victories in this expedition, the military strength of the Rashtrakutas and the prestige of the Rashtrakuta kingdom rose immensely.\n*   During his thirteen-year rule, Dhruva expanded the Rashtrakuta kingdom into a vast empire. In all these wars, his sons **Stambha, Karka, Govinda and Indra** helped him.\n\n### Govinda III (793 – 814 A.D.)\n\nAfter Dhruva, his son Govinda III assumed power — the greatest among the Rashtrakutas. His titles included \"Prabhutavarsha,\" \"Rajadhiraja,\" \"Rajaparameswara,\" \"Tribhuvanadhavali,\" \"Sri Vallabha,\" \"Janavallabha\" and \"Kirthinarayana.\"\n\n**Wars and conquests**\n\n*   The **Sanjan inscription** records his greatness and victories. He fought wars with the Pallava, Western Ganga, Ghurjara-Pratihara and Pala kings, achieving success in all.\n*   He defeated Pratihara king **Nagabhata II**.\n*   He ruled for 22 years, spending his entire lifetime waging wars. His conquests extended to Chitrakuta, Ujjaini, Bengal, Kalapriya and the Ganga-Yamuna coastal plain.\n*   The ruler of Simhala country (Sri Lanka) became his friend. Broach ruler Sribhavana also maintained good relations with him.\n*   When Govinda III was on his Northern expedition, the Pallava, Pandya, Kerala and Ganga kings formed themselves into a confederacy against him; learning of this, he made lightning attacks on them, and by 802 A.D. this confederacy was broken.\n\nThrough these achievements, Govinda III became famous as a great warrior, commander-in-chief and statesman among the Rashtrakuta emperors. During his reign, the name and fame of the Rashtrakutas reached its highest level.\n\n### Amoghavarsha (814 – 880 A.D.)\n\nAfter Govinda III, his only son Amoghavarsha ruled — his original name was **Saru**. As he was a minor when he came to the throne, his uncle Indra''s son **Karka** took up the administrative responsibility of the kingdom as his protector.\n\n**Wars and diplomacy**\n\n*   Amoghavarsha''s reign was filled with rebellions, internal conflicts and wars. He defeated the Vengi king, **Gunaga Vijayaditya**.\n*   In South Indian politics, he strengthened his relations with some royal dynasties through marriage alliances.\n*   In the South, Gangavadi king Nitidurga declared his independence; Amoghavarsha defeated him but, with political foresight, gave back his kingdom to him, and gave his daughter Chandrabbalachhen in marriage to the Ganga king''s son, **Butuga**.\n*   Another daughter, Renuka (Revaka) Nirmadi (Sankha), was given in marriage to the Pallava king, **Nandi Varma**.\n*   He gave his sister in marriage to the Vengi crown-prince **Vishnuvardhana VII**. Eastern Chalukyan ruler **Gunaga Vijayaditya** became his feudatory.\n\n**Literary and religious patronage**\n\n*   Not only in political and military fields, but also in religious and literary fields, Amoghavarsha''s contribution was great.\n*   He was a great poet — he wrote \"**Kavirajamarga**,\" the first \"alankara\" (rhetoric) work, and also \"**Prasnottara Ratnamalika**.\" He held the title \"Kaviraja.\"\n*   Jain poets of his period, **Mahavira Acharya** and **Saktayana**, wrote \"**Ganitasara Sangraha**\" and \"**Amoghavritti**\" respectively.\n*   Amoghavarsha built **Manyakheta (Malkhed)** city and made it his capital.\n*   The Arab traveller **Suleman**, describing Amoghavarsha''s activities, praised him as one of the four great emperors in the world.\n*   In order to stop a famine and pestilence in his kingdom, Amoghavarsha offered his left-hand finger as a sacrifice to the Mahalakshmi goddess at Kolhapur.\n*   Amoghavarsha adopted **Jainism**, observed \"Sallekhanavrata,\" and died.\n\n### Krishna II (880 – 914 A.D.)\n\nAfter Amoghavarsha, his son Krishna II became king. **From his time onward, the decline of the Rashtrakutas began.**\n\n*   Continuous wars were fought with the Pratihara, Kalinga, Ganga and Magadha kingdoms.\n*   Ghurjara-Pratihara king **Mihira Bhoja** swooped on the Rashtrakuta kingdom.\n*   Eastern Chalukya king **Gunaga Vijayaditya** invaded the Rashtrakuta kingdom and destroyed the cities of Kiranapura, Achalapura and Chakrakuta.\n*   Krishna II clashed with Chola king **Parantaka** and was defeated.\n*   Krishna II gave his daughter in marriage to Chola king **Aditya I**.\n\nThe reign of Krishna II, who faced defeats in many wars, shook the very foundations of the Rashtrakuta Empire.\n\n### Later Rashtrakutas\n\n*   After Krishna II, **Indra III (914 – 928 A.D.)** ruled. During his time, the Arab traveller **Al-Masudi** visited the Rashtrakuta kingdom.\n*   **Amoghavarsha II (928 – 929 A.D.)** and **Govinda IV (930 – 936 A.D.)** ruled next. Govinda IV, disgusted with the rebellions of the Mudigonda Chalukyas, gave up the kingdom and ran away.\n*   As a result, **Amoghavarsha III (936 – 939 A.D.)**, Govinda IV, and **Krishna III (939 – 966 A.D.)** ruled the Rashtrakuta kingdom in succession.\n\n**Krishna III — restoration of prestige**\n\n*   During the time of Krishna III, Rashtrakuta prestige was restored. He invaded the Chola kingdom; crown-prince **Rajaditya** was killed, and Krishna III assumed the title \"Tanjavoor Konda.\"\n*   In the **Takkolam battle**, Parantaka Chola I was defeated, and a victory pillar was erected at Rameswaram.\n*   A Northern Indian expedition was also made, and the Ujjain ruler **Mahipala** was defeated.\n\n**Khottiga (967 – 972 A.D.)**\n\n*   After Krishna III, his brother Khottiga became ruler.\n*   Malwa king **Harshaseyaka** defeated Khottiga and destroyed Manyakheta, and Khottiga, highly grief-struck over this insult, died.\n\n### Karkaraja II (972 – 973 A.D.) — End of the Rashtrakuta Dynasty\n\nAmong the Rashtrakutas, the last ruler was Karkaraja II. During his time, feudatories became independent.\n\nUnder these circumstances, **Chalukyan Tailapa**, the ruler of Tondavadi and a feudatory, defeated Karkaraja, killed him, and occupied Manyakheta; with this, the rule of the Rashtrakutas disappeared permanently, and Tailapa II established the rule of the Kalyani Chalukyan dynasty.\n\n### Rulers of the Rashtrakutas at a Glance\n\n| Ruler | Reign |\n|---|---|\n| Indra Raja I (founder, as feudatory) | 696 – 710 A.D. |\n| Govindaraja / Varma I | 710 – 725 A.D. |\n| Kanakaraja I | 725 – 735 A.D. |\n| Indraraja III | 735 – 748 A.D. |\n| Dantidurga (independence established) | 748 – 758 A.D. |\n| Krishna I | 758 – 772 A.D. |\n| Govinda II | 772 – 780 A.D. |\n| Dhruva Raja | 780 – 792 A.D. |\n| Govinda III | 793 – 814 A.D. |\n| Amoghavarsha | 814 – 880 A.D. |\n| Krishna II | 880 – 914 A.D. |\n| Indra III | 914 – 928 A.D. |\n| Amoghavarsha II | 928 – 929 A.D. |\n| Govinda IV | 930 – 936 A.D. |\n| Amoghavarsha III | 936 – 939 A.D. |\n| Krishna III | 939 – 966 A.D. |\n| Khottiga | 967 – 972 A.D. |\n| Karkaraja II (last ruler) | 972 – 973 A.D. |\n\n* * *", "free": true}, {"partNumber": 3, "conceptId": "telangana-history-en-chapter6-rashtrakutas-p3", "partName": "The Glory of the Rashtrakuta Empire", "bodyMd": "In the history of India itself, the Rashtrakuta rule period attained a distinction. The Rashtrakuta emperors, unrivalled, daring and war-like, not only established a vast empire that extended from Kanyakubja to Kanyakumari, but also introduced an effective system of administration for the welfare of the people, becoming popular rulers. These Rashtrakutas, who created a heroic age in the history of India, ruled in the interests of the people. In the beginning, **Ellichpur, Ellora and Paithan** cities remained their capitals; later, during Amoghavarsha''s reign, **Manyakheta** became the capital.\n\n### Administrative System\n\nIn the Rashtrakuta Empire, the king or emperor enjoyed absolute power and remained i' WHERE chapter_slug = 'telangana-history-en-chapter6-rashtrakutas';
UPDATE theory_content SET concepts_json = concepts_json || 'ndependent in statecraft. Authority over the kingdom was hereditary; Rashtrakuta kings assumed the titles \"Maharajadhiraja,\" \"Dharavarsha\" and \"Vikramavaloka.\"\n\n*   Though kingship was generally hereditary, there was a practice in those times that, on occasions when a son other than the eldest was found able and efficient, in the interests of the kingdom, he was made the ruler.\n*   The king used to be the commander-in-chief, and used to personally lead the armies during wars.\n*   The king''s court, full of ostentation and splendour, remained the symbol of his power and supremacy. Feudatories, foreign ambassadors, poets, doctors, astrologers, higher civil, military and government officials, and representatives of the Srenis (guilds) used to attend the king''s court.\n\n### Ministry\n\nMinisters used to assist the king in the administration of the kingdom. The important among them were called \"**Mahamantri**.\"\n\n*   The ministry included the Prime Minister, Finance Minister, Head of the Treasury, Law Minister, Commander-in-Chief and Purohita.\n*   Inscriptions have mentioned the posts of \"**Mahamatya**\" and \"**Mahasandhivigrahaka**.\"\n*   Kings and officials who were appointed at different places in the kingdom used to be called \"**Rajasthaneeya**.\"\n*   In the Rashtrakuta Empire, some parts of the empire were under the direct rule of the emperor, while others were under the rule of feudatories.\n*   Feudatories used to obey the orders of the emperor, pay tribute, and, as per agreement, supply armies to the king. Rashtrakuta kings took effective measures to ensure the feudatories did not rebel.\n\n### Local Administrative System\n\nThe kings divided the kingdom into **Rashtra, Vishaya and Villages**.\n\n| Unit | Head |\n|---|---|\n| Rashtra | Mahasamantha / Mahamandaleshwara (belonging to the status of feudatories) |\n| District (Vishaya) | Vishayapati / Bhogapati |\n| Town | Nagarapati |\n| Village | Gramapati |\n\n*   The Village Assembly, known as \"**Mahajanam**,\" belonged to the Agraharas. Combined village assemblies generally had a farmer assembly.\n\n### Army Organisation\n\nRashtrakutas maintained big armies — according to Altekar''s opinion, their army numbered less than five lakhs.\n\n*   Generally, the major part of the army was kept at the capital. Infantry had greater importance within the army.\n*   Soldiers belonging to all Varnas are seen in their army organisation. Members of Jainism, such as **Bankaya and Sri Vijaya**, served as commanders-in-chief.\n*   For soldiers who died in war, the government used to give relief or a pension. Commanders, just like feudatories, enjoyed control over elephants, cavalry and chariots.\n*   Merchants, during the time of expeditions, used to sell supplies in large quantities for army needs.\n*   The police staff of those days consisted of \"**Chorodharinukulu**\" and \"**Dandaposikulu**.\"\n\n### Revenue Administration\n\n**Land tax** was the main source of income to the kingdom.\n\n*   Besides this, a tax known as \"**Padenala tax**\" was levied for army maintenance. \"**Sandhi Vigraha**\" tax was imposed for the defence of the kingdom.\n*   Heavy duties, in the form of transit duties and market duties, were collected from native and foreign merchants.\n*   As the monarchical form of government took root, the tax burden on the people began to increase. Taxes were, in many instances, collected in installments.\n*   Though taxes to a greater extent were remitted in the form of grain, payments in cash were also made.\n*   There used to be a tax on the wheels that drew water for the fields. Among the property taxes — besides land tax — were house tax, oil-mill tax, cattle tax, sheep-herd tax and shop tax.\n\n**Distribution of income:** Out of the income received, it is learnt that **three parts** went to army maintenance, **one part** was kept as reserve fund, and **1/12th share** was spent on charities, the palace, and maintenance of the kingdom.\n\n*   On average, **15%** was left to the **Kudivaram** (local village officers) for the use of the people. Besides this, **1/3%** from the **Melavaram** was given by the central government for people''s welfare activities.\n\n### Judicial Administration\n\nThe king remained the main judicial head. Judicial administration was carried through the \"**Dharmasana**\" that belonged to the Grama Sabha. Activities against the king and the monarchy were personally examined by the king, and punishments were awarded.\n\n* * *", "free": false}, {"partNumber": 4, "conceptId": "telangana-history-en-chapter6-rashtrakutas-p4", "partName": "Rashtrakuta Age: Economic Conditions", "bodyMd": "For the economic development of the Rashtrakuta times, agriculture, industries, village crafts and commerce all contributed.\n\n### Agriculture\n\nAgriculture was the primary basis for the economic organisation.\n\n*   Because of the land grants made for the maintenance of the employer, extensive lands were brought under cultivation. Arab historians wrote that in Western India, land was fertile and paddy and fruits were in plenty; jowar and bajra were cultivated.\n*   Mango and toddy gardens were kept in an extensive manner; in Karnataka, betel-nut gardens were grown extensively.\n*   In South India, agricultural land was specially referred to as \"**Yeripatti**\" or \"**Cheruvukattu**\" land. Agriculture that depended on tanks was very much prevalent across the entire peninsula.\n*   The agriculturist used to pay one-sixth or one-tenth of the crop from the land as tax. Besides this, for the maintenance of tanks and other irrigation sources, temples, and other expenses, agriculturists used to pay several local taxes.\n\n### Industries\n\nThe **textile industry** became famous among all the industries. Gujarat, Berar and Telangana remained important centres for these industries; cloth manufactured in greater quantities used to be exported to foreign countries.\n\n*   Persons belonging to different industries got organised into guilds.\n*   Besides the cloth and spinning industries, spices, sandalwood, timber, teakwood and leather industries also existed.\n\n### Varied Crafts\n\nIt is learnt that in the Rashtrakuta kingdom''s village administration, not only administrative officials but persons belonging to twelve crafts contributed, and with their cooperation village administration went on properly.\n\n*   **Twelve crafts:** Grasti, talari, astrologer, blacksmith, potter, carpenter, washerman, barber, village teacher, leather worker and weaver craftsmen were part of it.\n*   There used to be **eighteen crafts people** in total: farmers, sheep and cattle breeders, handloom weavers, clerks, shop owners, soldiers, artists, scholars and traders. Crafts thus found a place in the economic life of those times.\n\n### Trade and Commerce\n\nTrading did not actively develop very much.\n\n*   The work \"**Cosmos Indicopleustes**\" mentioned the trade that went on between the Eastern and Western coastal areas of South India and Southwest Asian countries. **Pepper, cardamom and pearls** had been the main articles of export.\n*   It was clearly evident that during this period there was an increase in the importing of horses from the northwestern border. **Textiles**, their related industries, metal industry and carpentry developed during this period.\n*   For the most part, all this trade got confined to the respective local areas only, but trade in the 11th and 12th centuries A.D. received new vigour.\n*   **Craft guilds** such as \"**Manigaram**,\" \"**Nanadeseeyulu**\" and \"**Tissaiva Aayutta Aainnurvar**\" systematised trade in the South. Among these, \"**Aainnurvar**\" or \"**Ayyavolepura**\" (\"500 Swamies\") was a trade guild that attained much prominence — its members visited all regions in India, as well as Persia and Southeast Asian countries, and were the judicial protectors of leading merchants.\n*   \"**Manigaram**\" was the local trade guild; \"**Nagaram**\" meant an organised sales centre in South India.\n*   Trade with China and Sri Vijaya countries was an event that deserved recognition during this age.\n*   **Port towns:** Mahabalipuram, Nagapattanam, Kaveripattanam, Motupalli and Krishnapatnam on the Eastern coast, and Chaul, Sopara and Calicut on the Western coast, were famous port towns.\n\n* * *", "free": false}, {"partNumber": 5, "conceptId": "telangana-history-en-chapter6-rashtrakutas-p5", "partName": "Rashtrakuta Age: Social Organisation", "bodyMd": "In South India and the Deccan, the social structure essentially remained as per the \"**Varnasrama Dharma**\" and the four-fold division of the varnas. Inscriptions of all periods state that rulers continued to uphold Varnasramadharma.\n\n### Brahmins\n\nAs Brahmins had prominence in religious and ritual rites, they occupied a unique and higher place in society.\n\n*   Just like commanders and ministers, Brahmins took up military and administrative professions, increasing their economic potential and playing a significant role.\n*   As Vedic literature was studied with tax exemption, they received Agraharas and \"**Brahmadeyas**\" from the kings as donations.\n*   From the 10th and 11th centuries A.D. onward, as temples developed as organisations, the Brahmadeyas declined; besides this, as the importance of the craftsmen and merchant classes began to increase, the economic condition of the Brahmins went down, with only theoretical religious significance remaining.\n*   On account of invasions, Brahmins resorted to migration; the Malkhed Rashtrakutas brought with them many Purohit families. Depending on the geographical divisions in which the Brahmins resided, sects developed among them.\n*   The ruling class desired that the Kshatriya position should belong to them.\n\n### Kshatriyas\n\nRashtrakutas have been considered \"**Sat-Kshatriyas**\" — a special sub-sect among the Kshatriyas.\n\n*   Ordinary Kshatriyas used to follow the rites and rituals of the \"Dvijas.\" In order to increase their status, they used to claim or announce that their dynasties belonged to either the Chandra or Surya royal lineages.\n\n### Vaisyas\n\nVaisyas belonged to the trading and agricultural classes, and were called \"**Komaties**\" and \"**Seths**.\" Right from ancient times, they had an integrated organisation for carrying on their trading activities.\n\n### Sudras\n\nSudras mainly took up the occupations of agriculture, agricultural labour and military service.\n\n*   Because of the increased difference between Sudras and Chandalas, Sudras gained higher status; \"Rattadi\" or \"Reddi,\" \"Vellala\" and \"Kapu\" were the major Sudra classes.\n\n### Craftsmen, Labourers and Lower Status Groups\n\nUntil the 10th and 11th centuries A.D., craftsmen, labourers and Chandalas remained in lower status only. \"**Vetti Chakiri**\" (forced/unpaid labour) was condemned in \"**Yasastilaka**,\" a literary work of the 10th century A.D.\n\n*   Another development worth noting is that, alongside the emergence of the landlord-farmer class, in Karnataka and Tamil Nadu areas in the 9th and 10th centuries A.D., \"**Gurava**\" community persons were able to obtain the position of Purohit in Siva temples.\n*   The emergence of the crafts class \"**Panchanamvaru**\" in Andhra and \"**Edangai**\" in Tamil Nadu, in the 11th century A.D., deserves to be noted significantly. New religious movements such as **Virasaivism, Aaradhya Saivam and Sri Vaishnavam** were patronised by these craft classes and landlord farmers.\n\n### Progress of Education and Literature\n\nThe Rashtrakuta emperors showed a lot of interest in the development of education and literature, giving importance to the standards of higher education in the kingdom.\n\n**Educational patronage**\n\n*   The Rashtrakuta emperors and rich people used to donate Agraharas and lands to Brahmins. Agraharas used to be centres for Sanskrit education.\n*   Temple areas also developed as educational institutions — for instance, in the \"**Trayipurusha**\" temple at Selorgi in the Karnataka region, where a big college was located, there were **27 hostels**.\n*   Jain and Buddhist religions also imparted their own religious education. Students came from distant places for the sake of receiving education. Important cities and holy places developed as educational centres — **Malkhed, Nasik and Paithan** remained important among them.\n*   Subjects of higher education included Vedas, Grammar, Astrology, Literature, Philosophy, Dharmashastra, Puranas, Jurisprudence and Sanskrit education. Rashtrakuta kings patronised Sanskrit and Kannada literature.\n*   The **Dhulia inscription**, issued by Dhruva, records that grant-recipients were scholars in Vedas, Vedangas, Itihasas, Puranas, Grammar, Philosophy and Logic — Sanskrit grammar was stated to be the base for all the Sastras or sciences.\n*   In 975 A.D., land admeasuring 50 Mattaras (possibly around 200 acres) was donated to a Mutt located in the **Bhujabheswara temple** in Dharwad Mandal — students there had free education and food. Grants made to temples also appear to have included books for educational institutions and students.\n*   Temples and Agraharas of those days became, respectively, educational institutions and colleges. There was a Sanskrit educational institution at **Kaulas Agrahara** in Dharwad Mandal, where 200 Brahmin families remained well-versed in Grammar, Moral Science, Literature and Puranas.\n\n**Literature**\n\nSanskrit was the official language of the Rashtrakuta kingdom, and Jaina literature flourished during their rule.\n\n*   During the time of King Krishna III, **Halayudha** wrote \"**Kavirahasyam**,\" explaining the use of \"Sanskrit Dhatuvulu,\" along with a prasasti (praise) of emperor Krishna.\n*   **Jinasena**, the revered teacher of Amoghavarsha, wrote \"**Adipurana**\" — the biography of the Jain Tirthankaras — which was completed by his disciple **Gunachandra**.\n*   Jinasena, in his \"**Parsvabhyudayam**,\" applied every sloka line of \"Meghasandesam\" to the life of Jain Parsva, achieving a wonderful coordination of meaning.\n*   During Amoghavarsha''s time, a work on grammar titled \"**Amoghavritti**\" was written by **Sakatayana**, and another work titled \"**Ganitasarasangraha**\" was written by **Ganitayana Viracharya**.\n*   \"**Kavirajamarga**,\" the first work on poetics in the Kannada language, was authored by **Amoghavarsha** himself, who also wrote \"**Ratnamalika**\" and \"**Neetikavyam**.\"\n*   **Ponna**, second in the \"triumvirate\" of Kannada writers, was the court poet of Krishna III; he wrote \"**Shanti Puranam**.\"\n*   **Pampa**, the poet who was first in the Kannada triumvirate and a court poet of the Vemulavada Chalukyas (feudatories of the Rashtrakutas), wrote \"**Adipurana**\" and \"**Vikramarjuna Vijayam**.\"\n\n### Architecture\n\nIn place of earlier brick-and-timber structures, stone structures and cave temples were witnessed from the **6th and 7th centuries ' WHERE chapter_slug = 'telangana-history-en-chapter6-rashtrakutas';
UPDATE theory_content SET concepts_json = concepts_json || 'A.D.**\n\n*   The present-day Tamil Nadu and Kerala areas have been referred to as \"lower Dravidadesa,\" and Andhra and Karnataka areas as \"upper Dravidadesa\" — structures in lower Dravidadesa adopted the **Dravidian style**, while those in upper Dravidadesa stood as symbols for the spread of the **Nagara style**. These are seen in the 7th and 8th centuries A.D.\n\n**Ellora cave temples**\n\n*   During the time of the Rashtrakutas, cave temples were carved at Ellora. In the first cave, **Dantidurga built the Dasavatara temple**; the Nandi mandapam in this temple stands as an ancient monument of Rashtrakuta art.\n*   The **Kailasanatha temple at Ellora** was the artistic creation of **Krishna I**.\n    *   This rock-cut temple has a sanctum sanctorum, one mukhamandapam, and one roofed verandah or hall — the lower storey was not put to use.\n    *   The temple''s surface shows decorative foundation and pillar-like walls with shelves, in the same model as the storey in use.\n    *   The front has a projected mandapam and entrances on the north, south and west; at the centre of the roof of the mandapam, a lotus with huge wings has been carved.\n    *   The superstructure was in four storeys. The main temple of worship, seven small temples around it, and one Nandi mandapam are all there — following South Indian convention, the temple plan consisted of eight temples of worship in total.\n    *   The Gopuram (tower) had two storeys, with the upper part roofed in the shape of a hut-cart.\n    *   This temple holds all the forms of Siva found in sculptural science, standing as a repository for wonderful masterpieces of sculpture depicting episodes from the Hindu Puranas.\n*   Other famous structures include the \"**Chhota Kailasa**\" temple among the Ellora cave temples, the mandapa in front of the 15th cave, and the **Jain temple at Pattadakal**.\n\n### Sculpture\n\nThe Dasavatara temple was built with wonderful sculpture — its walls are decorated with images of Saiva and Vaishnava gods and goddesses. Among all its sculptures, the statue of **Narasimha killing Hiranyakasipa** became the most famous.\n\n*   In the Kailasanatha temple at the same Ellora, Siva''s images have been carved in great style of art. The cave temples on **Elephanta Island** near Bombay also have highly imposing images carved in stone.\n*   Among these sculptures, the statue of **Maheswara**, carved with the faces of the Trimurtis, not only stands as testimony to the great sculptural art of the Rashtrakutas but also became world-famous. The carving of Maheswara as the personification of creation, stability and destruction is highly commendable.\n\n### Painting\n\nThe paintings made on the walls and under the roofs of the Kailasanadha temple at Ellora stand as the best model for the art of painting of Rashtrakuta times. The paintings of **Nataraja, Lingodbhava and Vidhyadharulu** have been rendered in attractive colours and striking descriptive style.\n\n*   In painting, for the most part, the sculpture style was closely followed. The paintings in the Jaina cave, called \"**Indraprabha**,\" at Ellora, are characterised by beautiful style and broad, wide-open eyes.\n\n* * *", "free": false}, {"partNumber": 6, "conceptId": "telangana-history-en-chapter6-rashtrakutas-p6", "partName": "Rashtrakuta Age: Religious Developments", "bodyMd": "### Saivism\n\nLiterary and inscriptional sources prove that Saivism and its sects were in greater prevalence.\n\n*   In the Deccan, during the time of the Rashtrakutas, the \"**Kalamukha**\" and \"**Kapalika**\" sects came into vogue.\n*   Inscriptions of the 9th century A.D. show a new non-Brahmin devotee group known as \"**Gurava**\" came into existence — they had to take an oath of brahmacharya and then serve as Purohits in Siva temples.\n*   **Srisailam** came to be recognised as a great \"Kapalika\" centre.\n\n### Vaishnavism\n\nThe title \"**Sree Prithvi Vallabha**,\" borne by the Rashtrakuta kings, may have been intended to declare themselves as an avatara or incarnation of Vishnu.\n\n*   The worshipping of the avataras became an important characteristic of Vaishnavism. In the Deccan and South India, the \"**Narayana**\" concept became famous; Narayana, and Vishnu in sitting and standing postures, received much propagation. The Alvars praised Vishnu in these forms.\n*   In all, Vishnu in \"**Sayana**\" or lying posture was regarded as the highest stage, symbolising other-worldliness. The worship of Goddess **Lakshmi** was another important characteristic of Vaishnavism.\n*   During this time, **Srirangam, Kanchi, Ahobilam, Tirumala and Sreekurmam** were Vaishnava centres that attained eminence.\n\n### Buddhism\n\n**Huien-Tsang**, the famous Chinese traveller, mentioned that in Andhra, all permanent Buddhist residences were desolate, though there were many temples with a Brahmin base.\n\n*   **Sriparvatam** attained the status of an important centre for the worship of \"**Vajrapani Dharani**.\"\n*   **Vajrayana Buddhism** gained ground from the 7th century onward. This formed as a result of changes that occurred within Mahayana Buddhism, and is also called \"**Tantric Buddhism**.\" It implies three practices — **Vajrayana, Sahajayana and Kala Chakrayana** — an understandable practice.\n*   The teachers or professors in this movement were called \"**Siddhus**\"; their total number was **84**. Kalpanika Vedakas such as \"Mantra,\" \"Mudra\" and \"Mandala\" are implied in Vajrayana worship.\n*   By the 12th and 13th centuries A.D., **Amaravati, Guntupalli, Sriparvatam or Nagarjuna Konda, and Salihundam** in Andhra, along with **Nagapatnam and Kanchi**, remained as famous Buddhist centres.\n\n### Jainism\n\nDuring the time of the Rashtrakutas, Jainism had greater prominence than Buddhism and enjoyed patronage and influence.\n\n*   Officials and chiefs who were Jains were appointed in the Andhra area, contributing to the spread of Jainism. **Akalanka, Pampa and Ponna** were great persons associated with Jainism.\n*   Famous Jain sects — **Mulasangha, Yavaneeya and Dravidasangha** — were in circulation in Andhra. **Perur, Danuvulapadu, Vemulapadu, Ramathirtham, Hanumakonda, Patancheru and Kollipaka** had been famous Jain centres in Andhra.\n*   In the Karnataka region, the Rashtrakutas were the chief patrons of Jainism. Rashtrakuta king **Amoghavarsha I** and the figure **Chamundaraya** were famous patrons of Jainism. Among the several Jain centres, **Sravanabelagola** was the most famous. In Karnataka, the **Digambara** Jain sect was in practice.", "free": false}, {"partNumber": 7, "conceptId": "telangana-history-en-chapter6-rashtrakutas-p7", "partName": "Summary", "bodyMd": "Rashtrakutas played a prominent role in the history of South India and Telangana. It is a matter of pride that **Amoghavarsha I**, the Rashtrakuta emperor, was regarded by the contemporary Arab traveller **Suleiman** as one of the world''s renowned great emperors. The extension of the boundaries of their empire from Kanauj to Kanyakumari stands as testimony to their military victories, prowess and courage.\n\n*   Their system of administration achieved a fine balance between the strength of the central government and the freedom of local government. Through inscriptions and writings, the Rashtrakuta emperors contributed to the progress of the Kannada and Sanskrit languages.\n*   Though they patronised Jainism heavily, they showed a tolerant attitude not only towards Hinduism and Buddhism but also Islam, taking steps that contributed to their freedom and development.\n*   The fact that the Rashtrakutas, besides religion and literature, also contributed immensely to the development of architecture and sculpture indicates their great interest and love for cultural development.\n*   The **Dasavatara temple** at Ellora, the **Kailasanadha temple** at the same place, and the statue of **Maheswara** on Elephanta Island stand as great specimens of their rock-cut architecture; the knitting (lesu) method and feat of decoration make viewers spell-bound.\n\nNot only in Telangana, but even in the history of Dakshinapatha or South India as a whole, the period of Rashtrakuta rule glows in a striking and complete manner.", "free": false}]' WHERE chapter_slug = 'telangana-history-en-chapter6-rashtrakutas';
